var e={id:`lyset-for-hedningene`,episode:22,door:22,title:{nb:`Lyset for hedningene`,en:`The light for the gentiles`},reference:`Luk 2,32; Apg 10`,place:`cesarea`,prologue:[{image:`maps/cesarea-torg.webp`,text:{nb:`Simeon sa at barnet skulle bli et lys for hedningene. I Cæsarea, i huset til en romersk offiser, skjedde det.`,en:`Simeon said the child would be a light for the gentiles. In Caesarea, in the house of a Roman officer, it happened.`}},{image:`art/lukas.webp`,text:{nb:`Kornelius lever ennå, og en mann fra Roma har sjekket titlene i notatene. Holder det Lukas skriver, når noen prøver det?`,en:`Cornelius is still alive, and a man from Rome has checked the titles in the notes. Does what Luke writes hold up when someone tests it?`}}],intro:{nb:`Cæsarea ved havet, en morgen ved den store havna.`,en:`Caesarea by the sea, a morning at the great harbour.`},outro:{nb:`Lyset gikk fra templet til et romersk hus. Lukas tar med striden, og titlene hans stemmer. Ikke bevis, men slik ser en pålitelig forteller ut.`,en:`The light went from the temple to a Roman house. Luke keeps the quarrels in, and his titles are right. Not proof, but that is how a reliable narrator looks.`},map:[`################..##############`,`################..##############`,`##############....##############`,`#############.......############`,`############........############`,`#########......##.......########`,`##########.....###...###########`,`###########..........###########`,`###########.........############`,`######.#...###...##...##########`,`#####......###...##...##########`,`#####..#######...########.###..#`,`................................`,`..#.#..#.##..#....#..#..#..#.#..`,`########.##..#....#..#..########`,`#######..#############..########`,`#######..##############..#######`,`#######..##############..#######`,`#######..##############..#######`,`################################`,`################################`],background:`cesarea-torg.webp`,mood:`feast`,areas:[{id:`skrivestue`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######.....#########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`skrivestue.webp`,scale:1.8,ambience:`street`},{id:`kornelius-hus`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`stue.webp`,scale:1.8,ambience:`hearth`}],start:{x:15,y:10},entities:[{id:`lukas`,kind:`person`,x:16,y:10,name:{nb:`Lukas`,en:`Luke`},look:`luke`,portrait:`lukas.webp`,interactions:[{not:[`oppdrag`],say:[{nb:`Snakk med Kornelius og tjeneren hans, Filip og datteren, mannen fra Roma og den gamle. Gå inn i Kornelius’ hus og i skrivestua.`,en:`Talk to Cornelius and his servant, Philip and his daughter, the man from Rome and the old man. Go into Cornelius’ house and the writing room.`}],set:[`oppdrag`]},{has:[`huset-lost`,`lyset-lost`,`titler-sak-lost`,`striden-lost`,`kilden-lost`,`dagen-lost`],not:[`avsluttet`],say:[{nb:`Peter ville ikke komme, og Jerusalem ville ikke tro det. Jeg skriver det likevel.`,en:`Peter did not want to come, and Jerusalem did not want to believe it. I write it all the same.`},{nb:`I morgen: det vanskeligste av alt. En Messias som dør.`,en:`Tomorrow: the hardest of all. A Messiah who dies.`}],set:[`avsluttet`]},{has:[`spor:kornelius`],not:[`huset-lost`],say:[{nb:`Sakene venter i vitneboka.`,en:`The cases are waiting in the notebook.`}]},{say:[{nb:`Kornelius, tjeneren, Filip, datteren, mannen fra Roma, den gamle. Kornelius’ hus og skrivestua.`,en:`Cornelius, the servant, Philip, the daughter, the man from Rome, the old man. Cornelius’ house and the writing room.`}]}]},{id:`dor-skrivestue`,kind:`place`,x:14,y:2,name:{nb:`Skrivestua`,en:`The writing room`},look:`hotspot`,door:{area:`skrivestue`,x:15,y:14}},{id:`dor-kornelius`,kind:`place`,x:25,y:11,name:{nb:`Kornelius’ hus`,en:`Cornelius’ house`},look:`hotspot`,door:{area:`kornelius-hus`,x:15,y:14}},{id:`kornelius`,kind:`person`,x:12,y:8,name:{nb:`Kornelius`,en:`Cornelius`},look:`soldier`,portrait:`soldier.webp`,interactions:[{has:[`oppdrag`],not:[`spor:kornelius`],say:[{nb:`Jeg var centurion i den italiske kohorten. Romer, ikke jøde, men jeg ba til Israels Gud. En ettermiddag sa en mann i hvitt til meg: Send bud til Joppe etter Peter.`,en:`I was a centurion in the Italian cohort. A Roman, not a Jew, but I prayed to the God of Israel. One afternoon I saw a man in white: send to Joppa for Peter.`},{nb:`Peter kom, motvillig. Han sa rett ut at en jøde ikke går inn til en fremmed. Men Gud hadde vist ham at han ikke skulle kalle noe menneske urent.`,en:`Peter came, reluctantly. He said plainly that a Jew does not go into a foreigner’s house. But God had shown him that he was to call no one unclean.`},{nb:`Mens han talte om Jesus, kom Ånden over oss alle. Jødene som var med ham, sto og stirret. Så døpte han oss.`,en:`While he was speaking of Jesus, the Spirit came on all of us. The Jews who were with him stood and stared. Then he baptised us.`}],set:[`spor:kornelius`,`spor:peter-motvillig`,`fakta:kornelius`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{say:[{nb:`En gammel soldat som ba. Og Gud svarte.`,en:`An old soldier who prayed. And God answered.`}]}]},{id:`tjener`,kind:`person`,x:18,y:8,name:{nb:`Tjeneren som gikk til Joppe`,en:`The servant who went to Joppa`},look:`courier`,portrait:`courier.webp`,interactions:[{has:[`oppdrag`],not:[`spor:tjener`],say:[{nb:`Vi var tre som gikk, en lang dagsreise sør langs kysten til Joppe, til garveren Simons hus. Peter sto på taket.`,en:`Three of us went, a long day’s journey south along the coast to Joppa, to the house of Simon the tanner. Peter was on the roof.`},{nb:`Han hadde selv sett et syn: en duk full av dyr, og en røst som sa: slakt og spis. Han forsto det ikke før vi banket på.`,en:`He had seen a vision himself: a sheet full of animals, and a voice that said: kill and eat. He did not understand it until we knocked.`}],set:[`spor:tjener`]},{has:[`bud:2`],not:[`tre-bud`],say:[{nb:`Tre, som Lukas skrev: to tjenere og en from soldat. Nå har du hørt det fra to av oss.`,en:`Three, as Luke wrote: two servants and a devout soldier. Now you have heard it from two of us.`}],set:[`tre-bud`]},{has:[`tre-bud`],not:[],say:[{nb:`Garverens hus ved sjøen. Peter på taket.`,en:`The tanner’s house by the sea. Peter on the roof.`}],set:[]},{say:[{nb:`Vi var tre som gikk. Den andre tjeneren står nede på kaia; spør ham.`,en:`Three of us went. The other servant is down on the quay; ask him.`}]}]},{id:`filip`,kind:`person`,x:23,y:13,name:{nb:`Filip`,en:`Philip`},look:`james`,portrait:`james.webp`,interactions:[{has:[`oppdrag`],not:[`spor:filip`],say:[{nb:`Lukas har vært mye hos meg mens Paulus har sittet fanget her, og spurt meg ut: om Samaria, og om etiopieren med Jesaja-rullen i vogna.`,en:`Luke has been with me often while Paul has been held here, and has questioned me: about Samaria, and about the Ethiopian with the Isaiah scroll in his chariot.`},{nb:`Jeg var en av de sju som ble valgt i Jerusalem til å dele ut mat. Så ble vi spredt. Slik kom ordet til Samaria og hit: ved en strid om mat og en forfølgelse.`,en:`I was one of the seven chosen in Jerusalem to hand out food. Then we were scattered. That is how the word came to Samaria and here: by a quarrel about food and a persecution.`}],set:[`spor:filip`,`spor:etiopieren`,`fakta:filip`]},{say:[{nb:`Lukas spurte meg ut hver gang han kom. Han glemte ingenting.`,en:`Luke questioned me every time he came. He forgot nothing.`}]}]},{id:`datter`,kind:`person`,x:12,y:4,name:{nb:`Filips datter`,en:`Philip’s daughter`},look:`girl`,portrait:`girl.webp`,interactions:[{has:[`oppdrag`],not:[`spor:datter`],say:[{nb:`Vi er fire søstre som taler profetisk, sier folk; Joel lovte det, sier far. Lukas skrev ned det vi sa, og det far sa.`,en:`We are four sisters who prophesy, people say; Joel promised it, Father says. Luke wrote down what we said, and what Father said.`}],set:[`spor:datter`]},{say:[{nb:`Fire søstre. Joel lovte det.`,en:`Four sisters. Joel promised it.`}]}]},{id:`embetsmann`,kind:`person`,x:19,y:7,name:{nb:`Mannen fra Roma`,en:`The man from Rome`},look:`courier`,portrait:`courier.webp`,interactions:[{has:[`oppdrag`],not:[`spor:embetsmann`],say:[{nb:`Tretti år i keiserens forvaltning. Lukas ba meg se etter feil i titlene hans. Folk gjør alltid feil der: de sier «guvernør» om alle.`,en:`Thirty years in the emperor’s administration. Luke asked me to read his notes for mistakes in titles. People always get those wrong: they call everyone “governor”.`},{nb:`Han skriver «prokonsul» på Kypros og i Korint: riktig, begge hører under senatet. «Politarker» i Tessalonika: det ordet brukes nesten bare i Makedonia.`,en:`He writes “proconsul” on Cyprus and in Corinth: correct, both come under the senate. “Politarchs” in Thessalonica: that word is used almost only in Macedonia.`},{nb:`«Asiarker» og «byskriveren» i Efesos, «pretorer» i Filippi. Jeg fant ingen feil. Det er sjeldent.`,en:`“Asiarchs” and “the town clerk” in Ephesus, “praetors” in Philippi. I found no mistake. That is rare.`}],set:[`spor:embetsmann`,`spor:titler`,`fakta:sherwin-white`]},{has:[`spor:prefekt`,`spor:prokurator`],not:[`titler-sett`],say:[{nb:`Samme embete, to titler: prefekt før Claudius, prokurator etter. Den som skriver uten å vite det, snubler her. Lukas snubler ikke.`,en:`Same office, two titles: prefect before Claudius, procurator after. Anyone writing without knowing that trips up here. Luke does not trip.`}],set:[`titler-sett`]},{has:[`titler-sett`],not:[],say:[{nb:`Ingen feil i titlene. Det er sjeldent.`,en:`No mistake in the titles. That is rare.`}],set:[]},{say:[{nb:`Ingen feil i titlene. Finn steinen om Pilatus og brevet fra kanselliet her på torget, så viser jeg deg noe.`,en:`No mistakes in the titles. Find the stone about Pilate and the letter from the chancery here in the square, and I will show you something.`}]}]},{id:`gammel`,kind:`person`,x:26,y:13,name:{nb:`Den gamle fra Jerusalem`,en:`The old man from Jerusalem`},look:`beggar`,portrait:`beggar.webp`,interactions:[{has:[`oppdrag`],not:[`spor:gammel`],say:[{nb:`Da Peter kom tilbake til Jerusalem, gikk vi løs på ham: du har spist med uomskårne! Han måtte fortelle alt fra begynnelsen før vi ble stille.`,en:`When Peter came back to Jerusalem, we went for him: you have eaten with uncircumcised men! He had to tell everything from the beginning before we fell silent.`},{nb:`Og selv da var det mange som ikke likte det. Senere ble det et stort møte om saken. Og Paulus og Barnabas skilte lag etter en skarp krangel. Lukas skriver alt. Det hadde ikke jeg gjort.`,en:`And even then many did not like it. Later there was a great meeting about it. And Paul and Barnabas parted after a sharp quarrel. Luke puts it all in. I would not have.`}],set:[`spor:gammel`,`spor:strid`,`fakta:striden`]},{say:[{nb:`Vi gikk løs på ham. Lukas skriver det.`,en:`We went for him. Luke puts it in.`}]}]},{id:`fisker`,kind:`person`,x:14,y:6,name:{nb:`Fiskeren ved havna`,en:`The fisherman at the harbour`},look:`fisher`,portrait:`fisher.webp`,interactions:[{say:[{nb:`Vil du prøve garnet? Havna her er bygd av Herodes, ut i åpent hav, med steinblokker større enn hus. Skipene går til Roma herfra.`,en:`Want to try the net? The harbour here was built by Herod, out into the open sea, with stone blocks bigger than houses. The ships go to Rome from here.`}],play:{game:`fish`,title:{nb:`Kast garnet`,en:`Cast the net`},win:`spill-garn`}}]},{id:`havna`,kind:`thing`,x:16,y:14,name:{nb:`Utsikten mot havna`,en:`The view of the harbour`},look:`hotspot`,interactions:[{say:[{nb:`Moloen, fyret, lagerhusene, og et skip som gjør seg klart for Roma. Veien fra Jerusalem til Roma går over denne kaia.`,en:`The breakwater, the lighthouse, the warehouses, and a ship getting ready for Rome. The road from Jerusalem to Rome goes across this quay.`}],set:[`spor:havna`]}]},{id:`vei-jerusalem`,kind:`place`,x:31,y:12,name:{nb:`Veien til Jerusalem`,en:`The road to Jerusalem`},look:`hotspot`,travelTo:`jerusalem`},{id:`vei-torget`,kind:`place`,x:0,y:12,name:{nb:`Til dagen da skriverne kopierte`,en:`To the day the copyists worked`},look:`hotspot`,travel:`avskriftene`},{id:`dor-ut-kornelius`,kind:`place`,x:15,y:17,name:{nb:`Ut på torget`,en:`Out to the square`},look:`hotspot`,door:{area:`main`,x:25,y:12},area:`kornelius-hus`},{id:`bordet`,kind:`thing`,x:15,y:9,name:{nb:`Bordet`,en:`The table`},look:`hotspot`,interactions:[{say:[{nb:`Et langt bord. Her satt Peter og spiste med romere, første gang. Det var det Jerusalem reagerte på: ikke dåpen, men måltidet.`,en:`A long table. Here Peter sat and ate with Romans, for the first time. That was what Jerusalem reacted to: not the baptism, but the meal.`}],set:[`spor:bordet`]}],area:`kornelius-hus`},{id:`hjelmen`,kind:`thing`,x:23,y:7,name:{nb:`Centurionens hjelm`,en:`The centurion’s helmet`},look:`hotspot`,interactions:[{say:[{nb:`En hjelm med tverrkam, hengt på veggen. Kornelius bar den i tretti år. Han tok den av i dette rommet, sier han, da Peter kom inn.`,en:`A helmet with a transverse crest, hung on the wall. Cornelius wore it for thirty years. He took it off in this room, he says, when Peter came in.`}],set:[`spor:hjelmen`]}],area:`kornelius-hus`},{id:`husfolk`,kind:`person`,x:20,y:9,name:{nb:`Kona i huset`,en:`The woman in the house`},look:`bakerwife`,portrait:`bakerwife.webp`,interactions:[{has:[`oppdrag`],not:[`spor:husfolk`],say:[{nb:`Vi var mange her den dagen: slekt, venner, tjenere. Hele huset ble døpt. Jeg var ung tjenestejente; jeg husker at jødene som kom med Peter, ikke ville sette seg først.`,en:`There were many of us here that day: family, friends, servants. The whole house was baptised. I was a young servant girl; I remember that the Jews who came with Peter would not sit down at first.`}],set:[`spor:husfolk`]},{say:[{nb:`Hele huset. Jeg var ung.`,en:`The whole house. I was young.`}]}],area:`kornelius-hus`},{id:`dor-ut-skrivestue`,kind:`place`,x:15,y:17,name:{nb:`Ut på torget`,en:`Out to the square`},look:`hotspot`,door:{area:`main`,x:15,y:2},area:`skrivestue`},{id:`simeon-ord`,kind:`thing`,x:15,y:9,name:{nb:`Simeons ord`,en:`Simeon’s words`},look:`hotspot`,interactions:[{say:[{nb:`Et ark fra begynnelsen av boka mi: den gamle i templet med barnet på armen, et lys for folkeslagene og en ære for Israel. Jeg satte strek under «folkeslagene».`,en:`A sheet from the beginning of what I write: the old man in the temple with the child in his arms, a light for the nations and a glory for Israel. I underlined “the nations”.`}],set:[`spor:simeon-ord`]}],area:`skrivestue`},{id:`jesaja49`,kind:`thing`,x:22,y:7,name:{nb:`Jesajas ord om lyset`,en:`Isaiah’s words on the light`},look:`hotspot`,interactions:[{say:[{nb:`Jesaja om Herrens tjener: Jeg gjør deg til et lys for folkeslagene, så frelsen min når helt til jordens ende. Simeon hørte dette i barnet; Paulus siterte det til hedningene.`,en:`Isaiah on the Lord’s servant: I will make you a light for the nations, so that my salvation reaches the farthest edge of the world. Simeon heard this in the child; Paul quoted it to the gentiles.`}],set:[`spor:jesaja49`]}],area:`skrivestue`},{id:`titlene`,kind:`thing`,x:8,y:7,name:{nb:`Lista over titler`,en:`The list of titles`},look:`hotspot`,interactions:[{say:[{nb:`En liste over byer og titlene på dem som styrer. Kypros: prokonsul. Filippi: pretorer. Tessalonika: politarker. Aten: Areopagos. Korint: prokonsul Gallio. Efesos: asiarker og byskriver.`,en:`A list: city, and what the ruler there is called. Cyprus: proconsul. Philippi: praetors. Thessalonica: politarchs. Athens: the Areopagus. Corinth: proconsul Gallio. Ephesus: Asiarchs and town clerk.`},{nb:`Mannen fra Roma har lest den. Ingen strek.`,en:`The man from Rome has read it. Nothing crossed out.`}],set:[`spor:titlene`]}],area:`skrivestue`},{id:`notat`,kind:`thing`,x:18,y:9,name:{nb:`Lukas’ notat`,en:`Luke’s note`},look:`hotspot`,interactions:[{say:[{nb:`Et ark: «Til den andre delen: selv med fra Troas, og her i Cæsarea mens Paulus sitter fanget. Filip: spurt mange kvelder. Kornelius: selv, i huset hans. Striden: de gamle i menigheten.»`,en:`A sheet: “For the second part: there myself from Troas, and here in Caesarea while Paul is a prisoner. Philip: asked on many evenings. Cornelius: himself, in his house. The quarrel: the church elders.”`},{nb:`«Der jeg ikke var, skriver jeg ‘de’; der jeg var, skriver jeg ‘vi’.»`,en:`“Where I was not, I write ‘they’; where I was, I write ‘we’.”`}],set:[`spor:notat`]}],area:`skrivestue`},{id:`kart`,kind:`thing`,x:26,y:9,name:{nb:`Kartet over reisene`,en:`The map of the journeys`},look:`hotspot`,interactions:[{has:[],not:[],set:[`spor:kart`],say:[{nb:`Et kart med en linje fra Jerusalem gjennom Samaria og Cæsarea, Antiokia, Kypros, Lilleasia og Hellas, og en stiplet linje mot Roma, dit Paulus lengter. Lyset går utover, by for by.`,en:`A map with a line from Jerusalem through Samaria and Caesarea, Antioch, Cyprus, Asia Minor and Greece, and a dotted line towards Rome, where Paul longs to go. The light goes outward, city by city.`},{nb:`Lukas: «Følg lyset slik det gikk: fra Jerusalem, gjennom Samaria med Filip, ned til Joppe der Peter bodde, og hit til Cæsarea, til Kornelius’ hus.»`,en:`Luke: “Follow the light the way it went: from Jerusalem, through Samaria with Philip, down to Joppa where Peter stayed, and here to Caesarea, to Cornelius’ house.”`}],play:{game:`trace`,title:{nb:`Lysets vei`,en:`The road of the light`},win:`lysets-vei-fulgt`,data:{points:[{x:58,y:59,name:{nb:`Jerusalem`,en:`Jerusalem`}},{x:48,y:38,name:{nb:`Samaria`,en:`Samaria`}},{x:23,y:57,name:{nb:`Joppe`,en:`Joppa`}},{x:36,y:21,name:{nb:`Cæsarea`,en:`Caesarea`}}]},key:!0}}],area:`skrivestue`},{id:`tjener-2`,kind:`person`,x:3,y:13,name:{nb:`Den andre tjeneren`,en:`The other servant`},look:`courier`,portrait:`courier.webp`,interactions:[{has:[`spor:tjener`],not:[`bud:2`],say:[{nb:`Jeg gikk også, og en from soldat med oss. Garverens hus luktet lær helt ut på gata.`,en:`I went too, and a devout soldier with us. The tanner’s house smelled of leather all the way out into the street.`},{nb:`Jøder holder seg unna garvere, for lukten og for de døde dyrene. At Peter bodde der, sier kanskje noe om hvor han alt var på vei.`,en:`Jews keep away from tanners, for the smell and the dead animals. That Peter lodged there perhaps says something about where he was already headed.`}],set:[`bud:2`]},{has:[`bud:2`],say:[{nb:`Vi var tre som gikk.`,en:`There were three of us who went.`}]},{say:[{nb:`Spør Kornelius’ tjener først, han ved huset.`,en:`Ask Cornelius’ servant first, the one by the house.`}]}]},{id:`innskrift-prefekt`,kind:`thing`,x:9,y:5,name:{nb:`Innskriften: Pilatus, prefekt`,en:`The inscription: Pilate, prefect`},look:`hotspot`,interactions:[{say:[{nb:`En stein til ære for Tiberius: «Pontius Pilatus, prefekt i Judea.»`,en:`A stone in honour of Tiberius: “Pontius Pilate, prefect of Judea.”`}],set:[`spor:prefekt`]}]},{id:`innskrift-prokurator`,kind:`thing`,x:28,y:13,name:{nb:`Et dokument fra kanselliet`,en:`A document from the chancery`},look:`hotspot`,interactions:[{say:[{nb:`Et brev fra stattholderens kanselli, slik mannen fra Roma viser deg det: «Felix, prokurator.» Samme sete som Pilatus, annen tittel.`,en:`A letter from the governor’s chancery, as the man from Rome shows it to you: “Felix, procurator.” The same seat as Pilate, a different title.`}],set:[`spor:prokurator`]}]},{id:`leke-baat`,kind:`thing`,x:24,y:16,name:{nb:`Båten ved brygga`,en:`The boat by the jetty`},look:`hotspot`,interactions:[{say:[{nb:`Du ror et lite stykke ut og inn igjen.`,en:`You rock out and back in again.`},{nb:`En gammel sjømann humrer: «Peter var fisker. Han hadde rodd bedre enn deg.»`,en:`An old sailor chuckles: “Peter was a fisherman. He would have rowed better than you.”`}],fx:`rock`}]},{id:`leke-frukt`,kind:`thing`,x:13,y:3,name:{nb:`Fruktboden`,en:`The fruit stall`},look:`hotspot`,interactions:[{say:[{nb:`Eplene triller utover. Selgeren roper: «Jøde eller greker, alle betaler for det de tråkker på!»`,en:`The apples roll away. The seller shouts: “Jew or Greek, everybody pays for what they tread on!”`}],fx:`tip`}]},{id:`leke-skaal`,kind:`thing`,x:14,y:13,name:{nb:`Bronseskåla`,en:`The bronze bowl`},look:`hotspot`,interactions:[{say:[{nb:`Klang! En romersk soldat snur seg brått, ser at det bare var deg, og sukker.`,en:`Clang! A Roman soldier spins round, sees that it was only you, and sighs.`}],fx:`ring`}]},{id:`leke-palme`,kind:`thing`,x:17,y:2,name:{nb:`Palmen`,en:`The palm tree`},look:`hotspot`,interactions:[{say:[{nb:`En daddel faller. Du deler den med en gutt som har fulgt med på deg hele tiden.`,en:`A date falls. You share it with a boy who has been watching you all along.`}],fx:`shake`}]},{id:`leke-vinde`,kind:`thing`,x:17,y:5,name:{nb:`Brønnvinda`,en:`The well windlass`},look:`hotspot`,interactions:[{say:[{nb:`Vinda knirker rundt. Filips datter rekker deg øsa: «Gjester først.»`,en:`The windlass creaks round. Philip’s daughter hands you the ladle: “Guests first.”`}],fx:`spin`}]}],facts:[{id:`kornelius`,title:{nb:`Kornelius og den italiske kohorten`,en:`Cornelius and the Italian cohort`},body:{nb:`Apg 10 kaller Kornelius centurion i «den italiske kohorten». En innskrift funnet i Carnuntum ved Donau viser at en cohors II Italica sto i Syria omkring år 69; om den sto i Cæsarea alt før år 41 (da Agrippa I overtok byen), er usikkert, men mulig. Cæsarea var Judeas romerske hovedstad med garnison. «Gudfryktige» som Kornelius, hedninger som ba til Israels Gud uten omskjærelse, er kjent fra innskrifter og fra Josefus. Lukas forteller om Kornelius tre ganger (Apg 10; 11,1–18; 15,7–11): for ham er dette vendepunktet der lyset går til hedningene. Lukas forteller at han ga mye til de fattige og ba til Gud sammen med hele huset sitt (Apg 10,2), og at Ånden kom over dem mens Peter talte, så de talte i tunger slik apostlene hadde gjort i Jerusalem (Apg 10,44–46; 11,15). Ofte kalles han den første hedningen som ble kristen; Lukas framstiller det slik, selv om etiopieren i Apg 8 også kan ha vært hedning.`,en:`Acts 10 calls Cornelius a centurion of “the Italian cohort”. An inscription found at Carnuntum on the Danube shows that a cohors II Italica was stationed in Syria around AD 69; whether it was already in Caesarea before AD 41 (when Agrippa I took over the city) is uncertain, but possible. Caesarea was Judea’s Roman capital with a garrison. “God-fearers” like Cornelius, gentiles who prayed to the God of Israel without circumcision, are known from inscriptions and from Josephus. Luke tells the Cornelius story three times (Acts 10; 11:1–18; 15:7–11): for him this is the turning point where the light goes to the gentiles. Luke says that he gave generously to the poor and prayed to God with his whole household (Acts 10:2), and that the Spirit came on them while Peter was speaking, so that they spoke in tongues as the apostles had done in Jerusalem (Acts 10:44–46; 11:15). He is often called the first gentile to become a Christian; Luke presents it that way, though the Ethiopian in Acts 8 may also have been a gentile.`},unlockedBy:`fakta:kornelius`,link:`https://bibleproject.com/videos/gospel-acts-2/`},{id:`sherwin-white`,title:{nb:`Sherwin-White og titlene`,en:`Sherwin-White and the titles`},body:{nb:`Kort sagt: Der Lukas kan sjekkes mot innskrifter, har han titlene riktig, men noen punkter er fortsatt omstridt. Romerrettshistorikeren A. N. Sherwin-White (Oxford) gikk i 1963 gjennom Apostlenes gjerninger mot det han visste om romersk rett og forvaltning, og konkluderte at bekreftelsen av historisiteten er «overveldende», og at ethvert forsøk på å avvise den, selv i detaljer, «må nå framstå som absurd». Eksempler: Sergius Paulus som prokonsul på Kypros (en senatsprovins; navnet Sergius Paullus er kjent fra innskrifter i Roma og Pisidia, men ingen av dem sikrer ham som prokonsul på Kypros akkurat da), Gallio som prokonsul i Akaia (Delfi-innskriften daterer ham til 51/52), «politarker» i Tessalonika (ordet var så godt som ukjent i litteraturen til innskrifter dukket opp; nå kjenner vi rundt sytti, de fleste fra Makedonia), «asiarker» i Efesos, «den første mann» på Malta (innskrift). Colin Hemer (1989) listet over åtti slike treff. Craig bruker dette som historisk samsvar: Lukas er en forfatter som har rett der han kan prøves. Lukas er likevel ikke uten omstridte punkter: Kvirinius’ folketelling (Luk 2,2), Teudas (Apg 5,36 mot Josefus) og Lysanias (Luk 3,1) diskuteres fortsatt. Sherwin-Whites dom gjelder Apostlenes gjerninger som helhet, ikke hver enkelt detalj. Sergius Paulus var prokonsul på Kypros og Gallio i Korint (Apg 13,7; 18,12); Kypros var senatsprovins fra 22 f.Kr., Akaia igjen fra år 44. Gallio var bror av filosofen Seneca. Flere av politark-innskriftene kommer fra Tessalonika selv. Lista i spillet tar også med Filippi, en romersk koloni med «pretorer» og «liktorer» (Apg 16,20.35), Areopagos i Aten (Apg 17,19) og byskriveren i Efesos (Apg 19,35).`,en:`In short, where Luke can be checked against inscriptions his titles are right, but a few points are still debated. The Roman legal historian A. N. Sherwin-White (Oxford) went through Acts in 1963, checking it against what he knew of Roman law and administration, and concluded that the confirmation of historicity is “overwhelming”, and that any attempt to reject it, even in details, “must now appear absurd”. Examples: Sergius Paulus as proconsul on Cyprus (a senatorial province; the name Sergius Paullus is known from inscriptions in Rome and Pisidia, but none of them secures him as proconsul of Cyprus at exactly that time), Gallio as proconsul of Achaia (the Delphi inscription dates him to 51/52), “politarchs” in Thessalonica (the word was all but unknown in literature until inscriptions turned up; now about seventy are known, most from Macedonia), “Asiarchs” in Ephesus, “the first man” on Malta (inscription). Colin Hemer (1989) listed over eighty such hits. Craig uses this as historical congruence: Luke is an author who is right where he can be tested. Luke is not without disputed points, though: the census of Quirinius (Luke 2:2), Theudas (Acts 5:36 against Josephus) and Lysanias (Luke 3:1) are still debated. Sherwin-White’s verdict concerns Acts as a whole, not every single detail. Sergius Paulus was proconsul on Cyprus and Gallio in Corinth (Acts 13:7; 18:12); Cyprus was a senatorial province from 22 BC, Achaia again from AD 44. Gallio was the brother of the philosopher Seneca. Several of the politarch inscriptions come from Thessalonica itself. The list in the game also includes Philippi, a Roman colony with “praetors” and “lictors” (Acts 16:20, 35), the Areopagus in Athens (Acts 17:19) and the town clerk in Ephesus (Acts 19:35).`},unlockedBy:`fakta:sherwin-white`},{id:`lyset`,title:{nb:`Lyset for folkeslagene`,en:`The light for the nations`},body:{nb:`Jesaja lar Herrens tjener bli «et lys for folkeslagene» (Jes 42,6; 49,6). Simeon bruker ordene over barnet (Luk 2,32), og Paulus siterer dem til hedningene i Antiokia i Pisidia (Apg 13,47). Lukas’ to bøker er bygd rundt denne linja: fra templet i Jerusalem (Luk 1) til Roma (Apg 28). Det er ikke tilfeldig at hedningelegen Lukas, trolig selv hedning, skrev til en greker og lot Simeons ord stå som program. Mellom Simeons ord i templet og dagen i Kornelius’ hus ligger det rundt førti år; Kornelius-fortellingen dateres gjerne til slutten av 30-tallet, men årstallet er usikkert.`,en:`Isaiah has the Lord’s servant become “a light for the nations” (Isa 42:6; 49:6). Simeon uses the words over the child (Luke 2:32), and Paul quotes them to the gentiles in Antioch in Pisidia (Acts 13:47). Luke’s two books are built around this line: from the temple in Jerusalem (Luke 1) to Rome (Acts 28). It is no accident that Luke the physician, probably a gentile himself, wrote to a Greek and let Simeon’s words stand as the programme. About forty years lie between Simeon’s words in the temple and the day in Cornelius’ house; the Cornelius story is usually dated to the late 30s, but the year is uncertain.`},unlockedBy:`lyset-lost`},{id:`filip`,title:{nb:`Filip og «vi»`,en:`Philip and “we”`},body:{nb:`Kort sagt: Forfatteren skriver «vi» når han reiser med Paulus, og bodde to år i byen der Filip bodde. Filip var en av de sju (Apg 6,5), forkynte i Samaria og for etiopieren (Apg 8), og bodde i Cæsarea med fire døtre som profeterte (Apg 21,8–9). Papias (ca. 110) sier han hørte fortellinger av Filips døtre i Hierapolis (Eusebius, Kirkehistorien 3,39). Eusebius kaller ham «apostelen», men de fleste mener det er evangelisten Filip fra Cæsarea som flyttet dit med døtrene, og at de to Filip-ene er blandet sammen alt i oldkirken. Fra Apg 16,10 skifter fortellingen til «vi»: forfatteren er med Paulus fra Troas, og er i Cæsarea de to årene Paulus satt fengslet der (Apg 24,27; 27,1). Mange forskere (F. F. Bruce, Craig Keener) peker på at forfatteren dermed kan ha hatt to år med tilgang til Filip, Jerusalem og Kornelius’ by; «vi» forsvinner riktignok i Cæsarea-kapitlene og dukker opp igjen når Paulus seiler (27,1). «Vi»-avsnittene er det sterkeste indre vitnesbyrdet om at forfatteren var Paulus’ reisefølge, slik Irenaeus sier. Noen (Vernon Robbins) har foreslått at «vi» bare var en skrivemåte for sjøreiser i antikken, men «vi» hos Lukas begynner og slutter på land og følger ikke skipene; de fleste avviser derfor forklaringen. «Vi» bodde i Filips hus i Cæsarea (Apg 21,8–10). De sju ble valgt da de gresktalende enkene ble oversett ved matutdelingen (Apg 6,1–6). I Samaria tok folk imot ordet, og Peter og Johannes kom ned fra Jerusalem (Apg 8,5–17); etiopieren var hoffmann hos dronningen av Etiopia og kjørte på veien ned mot Gaza (Apg 8,26–40). Joels løfte om at døtrene skal profetere (Joel 3,1; 2,28 i engelske bibler), siterer Peter i Apg 2,17.`,en:`In short, the author writes “we” when travelling with Paul, and spent two years in the town where Philip lived. Philip was one of the seven (Acts 6:5), preached in Samaria and to the Ethiopian (Acts 8), and lived in Caesarea with four daughters who prophesied (Acts 21:8–9). Papias (c. 110) says he heard stories from Philip’s daughters in Hierapolis (Eusebius, Church History 3.39). Eusebius calls him “the apostle”, but most think it is Philip the evangelist from Caesarea who moved there with his daughters, and that the two Philips were already confused in the early church. From Acts 16:10 the narrative shifts to “we”: the author is with Paul from Troas, and is in Caesarea during the two years Paul was imprisoned there (Acts 24:27; 27:1). Many scholars (F. F. Bruce, Craig Keener) point out that the author may thus have had two years of access to Philip, Jerusalem and Cornelius’ town; the “we” does disappear in the Caesarea chapters and returns when Paul sails (27:1). The “we” passages are the strongest internal testimony that the author was Paul’s travelling companion, as Irenaeus says. Some (Vernon Robbins) have suggested the “we” was merely an ancient convention for sea voyages, but Luke’s “we” begins and ends on land and does not track the ships; most therefore reject the explanation. “We” stayed in Philip’s house in Caesarea (Acts 21:8–10). The seven were chosen when the Greek-speaking widows were overlooked in the food distribution (Acts 6:1–6). In Samaria people received the word, and Peter and John came down from Jerusalem (Acts 8:5–17); the Ethiopian was an official of the queen of Ethiopia, travelling on the road down towards Gaza (Acts 8:26–40). Joel’s promise that daughters will prophesy (Joel 2:28) is quoted by Peter in Acts 2:17.`},unlockedBy:`fakta:filip`},{id:`striden`,title:{nb:`Striden om hedningene`,en:`The quarrel about the gentiles`},body:{nb:`Lukas skjuler ikke konfliktene: kritikken av Peter (Apg 11,1–3), møtet i Jerusalem (Apg 15), bruddet mellom Paulus og Barnabas (15,39). Paulus selv forteller om en enda skarpere strid i Antiokia, der han irettesatte Peter ansikt til ansikt (Gal 2,11–14); den har Lukas ikke med. Kritikere ser Lukas som en som glatter over; forsvarere svarer at han velger, men ikke dikter, og at Galaterbrevet og Apostlenes gjerninger forteller om den samme striden fra to sider. Forlegenhetskriteriet gjelder begge veier: det pinlige Lukas tar med, står sterkt.`,en:`Luke does not hide the conflicts: the criticism of Peter (Acts 11:1–3), the meeting in Jerusalem (Acts 15), the rupture between Paul and Barnabas (15:39). Paul himself tells of an even sharper quarrel in Antioch, where he rebuked Peter to his face (Gal 2:11–14); Luke does not include it. Critics see Luke as someone who smooths things over; defenders answer that he selects but does not invent, and that Galatians and Acts tell of the same quarrel from two sides. The criterion of embarrassment runs both ways: the embarrassing things Luke includes stand strong.`},unlockedBy:`fakta:striden`},{id:`cesarea`,title:{nb:`Cæsarea`,en:`Caesarea`},body:{nb:`Herodes den store bygde Cæsarea Maritima (22–10 f.Kr.) med en kunstig havn i åpent hav, teater, hippodrom og et tempel for Augustus. Byen var romernes hovedstad i Judea; her ble Pilatus-innskriften funnet i 1961, den eneste sikre innskriften som nevner ham; den kaller ham prefekt, mens Lukas bruker det allmenne «landshøvding». Her bodde Kornelius og Filip, her satt Paulus fengslet i to år, og herfra seilte han til Roma. Teatret, havna og akvedukten kan ses i dag. Felix’ tittel kjenner vi fra Tacitus og Josefus, ikke fra noen stein.`,en:`Herod the Great built Caesarea Maritima (22–10 BC) with an artificial harbour in the open sea, a theatre, a hippodrome and a temple for Augustus. The city was the Romans’ capital in Judea; here the Pilate inscription was found in 1961, the only certain inscription naming him; it calls him prefect, while Luke uses the general “governor”. Here lived Cornelius and Philip, here Paul was imprisoned for two years, and from here he sailed to Rome. The theatre, the harbour and the aqueduct can be seen today. Felix’ title we know from Tacitus and Josephus, not from any stone.`},unlockedBy:`spor:havna`},{id:`garveren`,title:{nb:`Garveren i Joppe`,en:`The tanner in Joppa`},body:{nb:`Peter bodde hos garveren Simon i Joppe (Apg 9,43; 10,6). Garving brukte skinn fra døde dyr og luktet vondt; Misjna regner garver blant yrkene som ga kona rett til å kreve skilsmisse (Ketubbot 7,10). Mange fortolkere ser det som et tegn på at Peter alt var på vei bort fra de strengeste renhetsreglene, men det er usikkert hvor mye Lukas legger i det. Fra Cæsarea til Joppe er det rundt 50 km langs kysten.`,en:`Peter stayed with Simon the tanner in Joppa (Acts 9:43; 10:6). Tanning used the hides of dead animals and smelled foul; the Mishnah counts tanners among the trades that gave a wife the right to demand a divorce (Ketubot 7:10). Many interpreters see it as a sign that Peter was already moving away from the strictest purity rules, but how much Luke means by it is uncertain. From Caesarea to Joppa is about 50 km along the coast.`},unlockedBy:`spor:tjener`},{id:`diktet`,title:{nb:`Hva er funnet på i denne episoden?`,en:`What is made up in this episode?`},unlockedBy:`dagen-lost`,body:{nb:`Tjenerne, kona i huset, mannen fra Roma, den gamle fra Jerusalem og fiskeren er funnet på, og det samme er det de sier. Kornelius, Filip og døtrene hans står i Apg 10 og 21,8–9, men ordene deres er diktet. Vi vet ikke om Kornelius levde da Lukas skrev. At «vi» bodde hos Filip, står i Apg 21,8–10. Hjelmen, bordet og lista over titler er laget for spillet.`,en:`The servants, the woman in the house, the man from Rome, the old man from Jerusalem and the fisherman are invented, and so is what they say. Cornelius, Philip and his daughters are in Acts 10 and 21:8–9, but their words are invented. We do not know whether Cornelius was alive when Luke wrote. That “we” stayed with Philip is in Acts 21:8–10. The helmet, the table and the list of titles are made for the game.`}}],clues:[{id:`kornelius`,source:{nb:`Kornelius`,en:`Cornelius`},text:{nb:`Centurion i den italiske kohorten, romer som ba til Israels Gud. Så en mann i hvitt: send bud etter Peter. Ånden kom over hele huset mens Peter talte; de ble døpt.`,en:`Centurion in the Italian cohort, a Roman who prayed to the God of Israel. Saw a man in white: send for Peter. The Spirit came on the whole house while Peter spoke; they were baptised.`},unlockedBy:`spor:kornelius`},{id:`peter-motvillig`,source:{nb:`Kornelius`,en:`Cornelius`},text:{nb:`Peter kom motvillig og sa rett ut at en jøde ikke går inn til en fremmed. Jødene som var med ham, sto og stirret.`,en:`Peter came reluctantly and said plainly that a Jew does not go into a foreigner’s house. The Jews with him stood and stared.`},unlockedBy:`spor:peter-motvillig`},{id:`tjener`,source:{nb:`Tjeneren som gikk til Joppe`,en:`The servant who went to Joppa`},text:{nb:`Peter bodde hos en garver i Joppe, og hadde selv sett et syn med en duk full av dyr: slakt og spis. Han forsto det ikke før de banket på.`,en:`Peter lodged with a tanner in Joppa, and had himself seen a vision with a sheet full of animals: kill and eat. He did not understand it until they knocked.`},unlockedBy:`spor:tjener`},{id:`husfolk`,source:{nb:`Kona i huset`,en:`The woman in the house`},text:{nb:`Slekt, venner og tjenere var samlet; hele huset ble døpt. Jødene som kom med Peter, ville ikke sette seg først.`,en:`Family, friends and servants were gathered; the whole house was baptised. The Jews who came with Peter did not want to sit down at first.`},unlockedBy:`spor:husfolk`},{id:`bordet`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Bordet der Peter spiste med romere. Det var måltidet Jerusalem reagerte på, ikke dåpen.`,en:`The table where Peter ate with Romans. It was the meal Jerusalem reacted to, not the baptism.`},unlockedBy:`spor:bordet`},{id:`filip`,source:{nb:`Filip`,en:`Philip`},text:{nb:`Lukas har vært mye hos Filip mens Paulus har sittet fanget i Cæsarea, og spurt ham ut: Samaria, og etiopieren med Jesaja-rullen. Filip var en av de sju fra matstriden i Jerusalem.`,en:`Luke has been with Philip often while Paul has been held in Caesarea, and has questioned him: Samaria, and the Ethiopian with the Isaiah scroll. Philip was one of the seven from the food quarrel in Jerusalem.`},unlockedBy:`spor:filip`},{id:`etiopieren`,source:{nb:`Filip`,en:`Philip`},text:{nb:`Ordet kom til Samaria og Cæsarea ved en strid om mat og en forfølgelse.`,en:`The word came to Samaria and Caesarea by a quarrel about food and a persecution.`},unlockedBy:`spor:etiopieren`},{id:`datter`,source:{nb:`Filips datter`,en:`Philip’s daughter`},text:{nb:`Fire søstre som taler profetisk, som Joel lovte. Lukas skrev ned det de og faren sa.`,en:`Four sisters who prophesy, as Joel promised. Luke wrote down what they and their father said.`},unlockedBy:`spor:datter`},{id:`embetsmann`,source:{nb:`Mannen fra Roma`,en:`The man from Rome`},text:{nb:`Tretti år i keiserens forvaltning. Leste Lukas’ notater for feil i titler. Folk sier «guvernør» om alle.`,en:`Thirty years in the emperor’s administration. Checked Luke’s notes for mistakes in titles. People call everyone “governor”.`},unlockedBy:`spor:embetsmann`},{id:`titler`,source:{nb:`Mannen fra Roma`,en:`The man from Rome`},text:{nb:`Prokonsul på Kypros og i Korint, politarker i Tessalonika, asiarker og byskriver i Efesos, pretorer i Filippi. Ingen feil. Det er sjeldent.`,en:`Proconsul on Cyprus and in Corinth, politarchs in Thessalonica, Asiarchs and town clerk in Ephesus, praetors in Philippi. No mistake. That is rare.`},unlockedBy:`spor:titler`},{id:`titlene`,source:{nb:`Lista over titler`,en:`The list of titles`},text:{nb:`By for by, med riktig navn på den som styrer. Rettet av mannen fra Roma: ingen strek.`,en:`City by city, with the right title for the ruler. Checked by the man from Rome: nothing crossed out.`},unlockedBy:`spor:titlene`},{id:`gammel`,source:{nb:`Den gamle fra Jerusalem`,en:`The old man from Jerusalem`},text:{nb:`Jerusalem gikk løs på Peter: du har spist med uomskårne! Han måtte fortelle alt fra begynnelsen før de tidde, og mange likte det ikke.`,en:`Jerusalem went for Peter: you have eaten with the uncircumcised! He had to tell everything from the beginning before they fell silent, and many did not like it.`},unlockedBy:`spor:gammel`},{id:`strid`,source:{nb:`Den gamle fra Jerusalem`,en:`The old man from Jerusalem`},text:{nb:`Et stort møte om saken, og Paulus og Barnabas som skilte lag etter en skarp krangel. Lukas skriver alt. Den gamle hadde ikke gjort det.`,en:`A great meeting about the matter, and Paul and Barnabas parting after a sharp quarrel. Luke puts it all in. The old man would not have.`},unlockedBy:`spor:strid`},{id:`simeon-ord`,source:{nb:`Simeons ord`,en:`Simeon’s words`},text:{nb:`Et lys som skal lyse for folkeslagene. Lukas satte strek under «folkeslagene» alt da.`,en:`A light that will shine for the nations. Luke drew a line under “the nations” even then.`},unlockedBy:`spor:simeon-ord`},{id:`jesaja49`,source:{nb:`Jesajas ord om lyset`,en:`Isaiah’s words on the light`},text:{nb:`Et lys for folkeslagene, så frelsen kan komme til verdens ytterste grense. Simeon hørte det i barnet; Paulus siterte det til hedningene.`,en:`A light for the nations, so that salvation may reach the farthest edge of the world. Simeon heard it in the child; Paul quoted it to the gentiles.`},unlockedBy:`spor:jesaja49`},{id:`notat`,source:{nb:`Lukas’ notat`,en:`Luke’s note`},text:{nb:`Selv med fra Troas, og her i Cæsarea mens Paulus sitter fanget. Filip spurt mange kvelder; Kornelius selv; de gamle om striden. «De» der han ikke var, «vi» der han var.`,en:`There himself from Troas, and here in Caesarea while Paul is a prisoner. Philip asked on many evenings; Cornelius himself; the older members about the quarrel. “They” where he was not, “we” where he was.`},unlockedBy:`spor:notat`},{id:`kart`,source:{nb:`Kartet over reisene`,en:`The map of the journeys`},text:{nb:`Jerusalem, Samaria, Cæsarea, Antiokia, Kypros, Lilleasia, Hellas, og en stiplet linje mot Roma, dit Paulus lengter. Lyset går utover, by for by.`,en:`Jerusalem, Samaria, Caesarea, Antioch, Cyprus, Asia Minor, Greece, and a dotted line towards Rome, where Paul longs to go. The light goes outward, city by city.`},unlockedBy:`lysets-vei-fulgt`}],deductions:[{id:`huset`,question:{nb:`Hva skjedde i Kornelius’ hus, og hvorfor var det så vanskelig?`,en:`What happened in Cornelius’ house, and why was it so hard?`},clues:[`kornelius`,`peter-motvillig`,`tjener`,`bordet`],steps:[{ask:{nb:`Hva fortalte Kornelius?`,en:`What did Cornelius tell you?`},clues:[`kornelius`,`peter-motvillig`],yes:{nb:`Synet, Peter som kom motvillig, Ånden over hele huset. Hva sa tjeneren om Joppe?`,en:`The vision, Peter who came reluctantly, the Spirit on the whole house. What did the servant say about Joppa?`},no:{nb:`Det er ikke Kornelius.`,en:`That is not Cornelius.`}},{ask:{nb:`Hva sa tjeneren om Joppe, og hva så du ved bordet?`,en:`What did the servant say about Joppa, and what did you see at the table?`},clues:[`tjener`,`bordet`],yes:{nb:`Duken med dyrene, og bordet der Peter spiste med romere. Hvorfor var det så vanskelig?`,en:`The sheet with the animals, and the table where Peter ate with Romans. Why was it so hard?`},no:{nb:`Det er ikke tjeneren eller bordet.`,en:`That is not the servant or the table.`}}],options:[{text:{nb:`Romere ble døpt uten å bli jøder først, og Peter spiste med dem`,en:`Romans were baptised without first becoming Jews, and Peter ate with them`},feedback:{nb:`Riktig. For en jøde var det urent å gå inn til en fremmed og spise med ham. Det trengtes to syn og Ånden før Peter gjorde det, motvillig. Slik skriver ingen om den fremste av de tolv for å pynte.`,en:`Right. For a Jew it was unclean to enter a foreigner’s house and eat with him. It took two visions and the Spirit before Peter did it, reluctantly. Nobody writes like that about the first of the twelve to flatter.`},correct:!0},{text:{nb:`Kornelius ble omskåret og jøde først`,en:`Cornelius was circumcised and became a Jew first`},feedback:{nb:`Nei. Det var nettopp det som var saken: ikke omskåret, ikke jøde, og likevel Ånden og dåpen. Derfor ble det strid.`,en:`No. That was exactly the point: not circumcised, not a Jew, and still the Spirit and baptism. That is why there was a quarrel.`}},{text:{nb:`Peter kom gjerne; for ham var det ingen vanskelighet å gå inn til en romer`,en:`Peter came gladly; for him there was no difficulty in going into a Roman’s house`},feedback:{nb:`Nei. Hør Kornelius: Peter sa rett ut at en jøde ikke går inn til en fremmed. Og jødene med ham ville ikke sette seg.`,en:`No. Listen to Cornelius: Peter said plainly that a Jew does not go into a foreigner’s house. And the Jews with him did not want to sit down.`}}],set:[`huset-lost`]},{id:`lyset`,question:{nb:`Hva har Kornelius med Simeon i templet å gjøre?`,en:`What does Cornelius have to do with Simeon in the temple?`},clues:[`simeon-ord`,`jesaja49`,`kart`],steps:[{ask:{nb:`Finn Simeons ord og Jesajas ord om lyset.`,en:`Find Simeon’s words and Isaiah’s words on the light.`},clues:[`simeon-ord`,`jesaja49`],yes:{nb:`Et lys for folkeslagene, til jordens ende. Hva så du på kartet?`,en:`A light for the nations, to the end of the earth. What did you see on the map?`},no:{nb:`Det er ikke Simeon eller Jesaja.`,en:`That is not Simeon or Isaiah.`}},{ask:{nb:`Hva så du på kartet over reisene?`,en:`What did you see on the map of the journeys?`},clues:[`kart`],yes:{nb:`Fra Jerusalem og utover mot Roma, by for by. Hva har Kornelius med Simeon å gjøre?`,en:`From Jerusalem outward towards Rome, city by city. What does Cornelius have to do with Simeon?`},no:{nb:`Det er ikke kartet.`,en:`That is not the map.`}}],options:[{text:{nb:`Simeon sa: lys for folkeslagene. Her skjedde det først`,en:`Simeon said: a light for the nations. Here it first happened`},feedback:{nb:`Riktig. Jesajas ord i Simeons munn, og så et romersk hus i Cæsarea. Derfor begynner jeg med en gammel mann i templet og følger lyset utover, slik Jesaja sa.`,en:`Right. Isaiah’s words in Simeon’s mouth, and then a Roman house in Caesarea. That is why I begin with an old man in the temple and follow the light outward, as Isaiah said.`},correct:!0},{text:{nb:`Ingenting; det er to forskjellige fortellinger, førti år fra hverandre, uten noe til felles`,en:`Nothing; they are two different stories, forty years apart, with nothing in common`},feedback:{nb:`Jo. Les Simeons ord og Jesajas: samme lys, samme folkeslag. Kornelius er det Simeon så.`,en:`They do. Read Simeon’s words and Isaiah’s: the same light, the same nations. Cornelius is what Simeon saw.`}},{text:{nb:`Ingenting. Kornelius-dagen er diktet for å gi Simeons ord en oppfyllelse`,en:`Nothing. The day with Cornelius was made up to give Simeon’s words a fulfilment`},feedback:{nb:`Nei. Kornelius står foran deg, og huset hans husker dagen. Streken mellom templet og huset er min, men den går mellom to punkter som finnes.`,en:`No. Cornelius stands in front of you, and his household remembers the day. The line from the temple to the house is mine, but it runs between two points that exist.`}}],set:[`lyset-lost`]},{id:`titler-sak`,question:{nb:`Hva betyr det at mannen fra Roma ikke fant feil i titlene?`,en:`What does it mean that the man from Rome found no fault in the titles?`},clues:[`embetsmann`,`titler`,`titlene`],steps:[{ask:{nb:`Hva sa mannen fra Roma?`,en:`What did the man from Rome say?`},clues:[`embetsmann`,`titler`],yes:{nb:`Prokonsul, politarker, asiarker, pretorer. Ingen feil. Hva så du på lista?`,en:`Proconsul, politarchs, Asiarchs, praetors. No mistake. What did you see on the list?`},no:{nb:`Det er ikke mannen fra Roma.`,en:`That is not the man from Rome.`}},{ask:{nb:`Hva så du på lista over titler?`,en:`What did you see on the list of titles?`},clues:[`titlene`],yes:{nb:`By for by, riktig navn, ingen strek. Hva betyr det?`,en:`City by city, the right name, nothing crossed out. What does it mean?`},no:{nb:`Det er ikke lista.`,en:`That is not the list.`}}],options:[{text:{nb:`Den som skriver, har vært der eller spurt noen som var. Bevis for alt er det ikke`,en:`The writer has been there or asked someone who was. It is not proof of everything`},feedback:{nb:`Riktig, og merk forbeholdet. Titler skifter fra by til by og år til år; den som dikter hjemmefra, bommer. Den som har rett i titlene, kan ta feil i annet. Men den som bommer der, stoler jeg ikke på.`,en:`Right, and note the reservation. Titles change from city to city and year to year; anyone making it up at home gets them wrong. Someone right on titles may be wrong elsewhere. Someone wrong on them, I would not trust.`},correct:!0},{text:{nb:`Det beviser at alt Lukas skriver, er sant`,en:`It proves that all Luke writes is true`},feedback:{nb:`Nei, det er for mye. Riktige titler viser at jeg kjenner verden jeg skriver om. Resten må prøves for seg.`,en:`No, that is too much. Correct titles show that I know the world I write about. The rest must be tested on its own.`}},{text:{nb:`Det betyr ingenting; alle som har reist litt, kan titlene i hver by, så det er lett å få rett`,en:`It means nothing; anyone who has travelled a little knows the titles in every city, so it is easy to get right`},feedback:{nb:`Nei. Hør mannen fra Roma: folk sier «guvernør» om alle. Politarker finnes nesten bare i Makedonia; den som ikke har vært der, kjenner ikke ordet.`,en:`No. Listen to the man from Rome: people call everyone “governor”. Politarchs exist almost only in Macedonia; whoever has not been there does not know the word.`}}],set:[`titler-sak-lost`]},{id:`striden`,question:{nb:`Hvorfor skriver Lukas om kranglene i menigheten?`,en:`Why does Luke write about the quarrels in the church?`},clues:[`gammel`,`strid`,`husfolk`],steps:[{ask:{nb:`Hva fortalte den gamle fra Jerusalem?`,en:`What did the old man from Jerusalem tell you?`},clues:[`gammel`,`strid`],yes:{nb:`Kritikk, et stort møte og et brudd. Hva sa kona i huset?`,en:`Criticism, a great meeting and a split. What did the woman in the house say?`},no:{nb:`Det er ikke den gamle.`,en:`That is not the old man.`}},{ask:{nb:`Hva sa kona i Kornelius’ hus?`,en:`What did the woman in Cornelius’ house say?`},clues:[`husfolk`],yes:{nb:`Jødene ville ikke sette seg. Hvorfor skriver jeg om alt dette?`,en:`The Jews did not want to sit down. Why do I write about all this?`},no:{nb:`Det er ikke kona i huset.`,en:`That is not the woman in the house.`}}],options:[{text:{nb:`Fordi det skjedde. Den som ville pynte på menigheten, hadde strøket det`,en:`Because it happened. Anyone wanting to polish the church would have cut it`},feedback:{nb:`Riktig. Peters motvilje, kritikken i Jerusalem, bruddet mellom Paulus og Barnabas: alt står. Da er jeg lettere å tro der jeg forteller om enighet. Jeg velger, men det jeg tar med, pynter jeg ikke på.`,en:`Right. Peter’s reluctance, the criticism in Jerusalem, the split between Paul and Barnabas: it all stands. That makes me easier to believe where I tell of agreement. I select, but what I include, I do not dress up.`},correct:!0},{text:{nb:`For å vise at Peter var en dårlig leder`,en:`To show that Peter was a bad leader`},feedback:{nb:`Nei. Peter gikk, til slutt, og han forsvarte det i Jerusalem. Jeg skriver motviljen og modet, og Paulus’ krangel skriver jeg også.`,en:`No. Peter went, in the end, and he defended it in Jerusalem. I write about the reluctance and the courage, and I write about Paul’s quarrel too.`}},{text:{nb:`Lukas skriver ikke om krangler; han lar menigheten stå som én flokk, slik den gamle ville`,en:`Luke does not write about quarrels; he lets the church stand as one flock, as the old man wanted`},feedback:{nb:`Jo. Den gamle sa det selv: han hadde ikke gjort det. Jeg gjør det. Striden om Kornelius står, og bruddet mellom Paulus og Barnabas.`,en:`He does. The old man said so himself: he would not have. I do. The quarrel about Cornelius stands, and the rupture between Paul and Barnabas.`}}],set:[`striden-lost`]},{id:`kilden`,question:{nb:`Hvor har Lukas det han skriver om Samaria og etiopieren fra?`,en:`Where does Luke get what he writes about Samaria and the Ethiopian from?`},clues:[`filip`,`etiopieren`,`datter`,`notat`],steps:[{ask:{nb:`Hva sa Filip og datteren hans?`,en:`What did Philip and his daughter say?`},clues:[`filip`,`etiopieren`,`datter`],yes:{nb:`Spurt ut mange kvelder; en av de sju; fire døtre. Hva står i notatet mitt?`,en:`Questioned on many evenings; one of the seven; four daughters. What is in my note?`},no:{nb:`Det er ikke Filip eller datteren.`,en:`That is not Philip or the daughter.`}},{ask:{nb:`Hva står i notatet mitt om vitnene?`,en:`What is in my note on the witnesses?`},clues:[`notat`],yes:{nb:`«De» der jeg ikke var, «vi» der jeg var. Hvor har jeg Samaria fra?`,en:`“They” where I was not, “we” where I was. Where do I get Samaria from?`},no:{nb:`Det er ikke notatet mitt.`,en:`That is not my note.`}}],options:[{text:{nb:`Trolig fra Filip selv, som var der, og som Lukas bodde hos i Cæsarea`,en:`Probably from Philip, who was there, and with whom Luke stayed in Caesarea`},feedback:{nb:`Riktig. Jeg skiller mellom det jeg så («vi») og det jeg fikk fortalt («de»), og jeg kan peke på hvem jeg spurte. Snart to år i denne byen, med Filip ved bordet: her har jeg samlet det meste.`,en:`Right. I keep apart what I saw (“we”) and what I was told (“they”), and I can point to whom I asked. Nearly two years in this town, with Philip at the table: here I have gathered most of it.`},correct:!0},{text:{nb:`Lukas var selv i Samaria og så det med egne øyne`,en:`Luke was in Samaria himself and saw it with his own eyes`},feedback:{nb:`Nei. Der skriver jeg «de». Jeg var ikke med før Troas, og Samaria var mange år før det.`,en:`No. There I write “they”. I did not join until Troas, and Samaria was many years before that.`}},{text:{nb:`Fra et brev som Peter sendte ham fra Jerusalem, med alt han husket fra Samaria`,en:`From a letter Peter sent him from Jerusalem, with all he remembered of Samaria`},feedback:{nb:`Nei. Fra Filip, ansikt til ansikt, kveld etter kveld. Peter var der også, men det er Filip jeg har spurt.`,en:`No. From Philip, face to face, evening after evening. Peter was there too, but it is Philip I have asked.`}}],set:[`kilden-lost`]},{id:`dagen`,question:{nb:`Hva skjedde mellom Cæsarea og Joppe, og i hvilken rekkefølge?`,en:`What happened between Caesarea and Joppa, and in what order?`},clues:[`kornelius`,`peter-motvillig`,`tjener`,`husfolk`,`gammel`,`strid`],steps:[{ask:{nb:`Finn Kornelius, tjeneren, kona i huset og den gamle fra Jerusalem.`,en:`Find Cornelius, the servant, the woman in the house and the old man from Jerusalem.`},clues:[`kornelius`,`peter-motvillig`,`tjener`,`husfolk`,`gammel`,`strid`],yes:{nb:`To syn, ett bud, ett hus og en strid. Men hva kom først? Sett det i rekkefølge.`,en:`Two visions, one errand, one house and a quarrel. But what came first? Put it in order.`},no:{nb:`Det hjelper ikke med rekkefølgen.`,en:`That does not help with the order.`}}],sequence:[{nb:`Kornelius ser en mann i hvitt: send bud til Joppe etter Peter`,en:`Cornelius sees a man in white: send to Joppa for Peter`},{nb:`Peter ser duken med dyrene på taket: slakt og spis`,en:`On the roof, Peter sees the sheet with the animals: kill and eat`},{nb:`Tre menn kommer fram til garverens hus og banker på`,en:`Three men arrive at the tanner’s house and knock`},{nb:`Peter går motvillig inn i Kornelius’ hus og taler om Jesus`,en:`Peter goes reluctantly into Cornelius’ house and speaks of Jesus`},{nb:`Ånden kommer over hele huset, og de blir døpt`,en:`The Spirit comes on the whole house, and they are baptised`},{nb:`Peter spiser med dem, og Jerusalem går løs på ham`,en:`Peter eats with them, and Jerusalem goes for him`}],explained:{nb:`Slik hang det sammen: to syn, én dagsreise, ett måltid, og en strid som varte i årevis. Lyset gikk utover, og det kostet.`,en:`That is how it fitted together: two visions, one day’s journey, one meal, and a quarrel that lasted for years. The light went outward, and it came at a cost.`},set:[`dagen-lost`]}],objectives:[{text:{nb:`Snakk med Lukas`,en:`Talk to Luke`},doneBy:[`oppdrag`]},{text:{nb:`Snakk med Kornelius, tjeneren, Filip, datteren, mannen fra Roma og den gamle`,en:`Talk to Cornelius, the servant, Philip, the daughter, the man from Rome and the old man`},doneBy:[`spor:kornelius`,`spor:tjener`,`spor:filip`,`spor:datter`,`spor:embetsmann`,`spor:gammel`]},{text:{nb:`Gå inn i Kornelius’ hus`,en:`Go into Cornelius’ house`},doneBy:[`spor:bordet`,`spor:hjelmen`,`spor:husfolk`]},{text:{nb:`Les arkene i skrivestua og følg lysets vei på kartet`,en:`Read the sheets in the writing room, and follow the light’s road on the map`},doneBy:[`spor:simeon-ord`,`spor:jesaja49`,`spor:titlene`,`spor:notat`,`spor:kart`,`lysets-vei-fulgt`]},{text:{nb:`Løs sakene i vitneboka`,en:`Solve the cases in the notebook`},doneBy:[`huset-lost`,`lyset-lost`,`titler-sak-lost`,`striden-lost`,`kilden-lost`,`dagen-lost`]},{text:{nb:`Gå tilbake til Lukas`,en:`Go back to Luke`},doneBy:[`avsluttet`]}],rewards:[{flag:`huset-lost`,points:15,label:{nb:`Forstå dagen i Kornelius’ hus`,en:`Understand the day in Cornelius’ house`}},{flag:`lyset-lost`,points:15,label:{nb:`Følg lyset fra Simeon`,en:`Follow the light from Simeon`}},{flag:`titler-sak-lost`,points:15,label:{nb:`Prøv titlene`,en:`Test the titles`}},{flag:`striden-lost`,points:15,label:{nb:`Se striden stå`,en:`See the quarrel left in`}},{flag:`kilden-lost`,points:15,label:{nb:`Finn kilden Filip`,en:`Find the source: Philip`}},{flag:`dagen-lost`,points:10,label:{nb:`Sett dagen i rekkefølge`,en:`Put the day in order`}},{flag:`avsluttet`,points:10,label:{nb:`Fullfør dagen med Lukas`,en:`Finish the day with Luke`}},{flag:`spill-garn`,points:10,label:{nb:`Kast garnet`,en:`Cast the net`},side:!0},{flag:`spor:havna`,points:5,label:{nb:`Se havna`,en:`See the harbour`},side:!0},{flag:`spor:hjelmen`,points:5,label:{nb:`Se centurionens hjelm`,en:`See the centurion’s helmet`},side:!0},{flag:`tre-bud`,points:10,label:{nb:`Finn den andre som gikk til Joppe`,en:`Find the other one who went to Joppa`},side:!0},{flag:`titler-sett`,points:10,label:{nb:`Les steinen og brevet, og spør mannen fra Roma`,en:`Read the stone and the letter, and ask the man from Rome`},side:!0},{flag:`lysets-vei-fulgt`,points:10,label:{nb:`Følg lysets vei`,en:`Follow the road of the light`},side:!0}],ambience:[{sound:`sea`,x:8,y:16,radius:8},{sound:`sea`,x:16,y:16,radius:8},{sound:`sea`,x:23,y:16,radius:8},{sound:`market`,x:12,y:4,radius:5},{sound:`market`,x:21,y:6,radius:5},{sound:`market`,x:15,y:8,radius:4}],goal:[`avsluttet`],solution:`lukas.kornelius.tjener.tjener-2.tjener.filip.datter.embetsmann.innskrift-prefekt.innskrift-prokurator.embetsmann.gammel.fisker.havna.dor-kornelius.bordet.hjelmen.husfolk.dor-ut-kornelius.dor-skrivestue.simeon-ord.jesaja49.titlene.notat.kart.dor-ut-skrivestue.huset.lyset.titler-sak.striden.kilden.dagen.lukas`.split(`.`)};export{e as default};